    char *path_copy = strdup(path);
    char *token = strtok(path_copy, "/");

    while (token != NULL) {
        if (strcmp(token, "..") == 0) {
            free(path_copy);
            return false;
        }
        token = strtok(NULL, "/");
    }

    free(path_copy);
    return true;
}

